package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.CompilerErrorCode;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CheckGlobalThis_visit_TriageGen1Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Compiler compiler;

    @Mock
    private CompilerErrorCode error;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        // Since we cannot easily instantiate CheckGlobalThis if it has private fields 
        // or specific constructor requirements not provided, we assume it follows 
        // standard JSComp pattern where compiler is injected or accessible.
        // For this test, we assume we can use reflection or that the class is testable.
        checkGlobalThis = new CheckGlobalThis();
        // Injecting the mock compiler into the instance via reflection if necessary, 
        // but here we assume a setter or field access is possible for the purpose of the test.
        setCompiler(checkGlobalThis, compiler);
    }

    private void setCompiler(CheckGlobalThis instance, Compiler compiler) {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("compiler");
            field.setAccessible(true);
            field.set(instance, compiler);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private void setAssignLhsChild(CheckGlobalThis instance, Node node) {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
            field.setAccessible(true);
            field.set(instance, node);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private Node getAssignLhsChild(CheckGlobalThis instance) {
        try {
            java.lang.reflect.Field field = CheckGlobalThis.class.getDeclaredField("assignLhsChild");
            field.setAccessible(true);
            return (Node) field.get(instance);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void testVisit_ThisIsReported() {
        // Setup: n is THIS and shouldReportThis returns true
        when(n.getType()).thenReturn(Token.THIS);

        // We need to mock shouldReportThis. Since it's a method in the same class, 
        // if it's not final, we'd use a spy. Assuming it's a standard method.
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.shouldReportThis(n, parent)).thenReturn(true);
        when(t.makeError(n, any(), any())).thenReturn(error);

        spyCheck.visit(t, n, parent);

        verify(compiler).report(error);
    }

    @Test
    public void testVisit_ThisIsNotReported() {
        // Setup: n is THIS but shouldReportThis returns false
        when(n.getType()).thenReturn(Token.THIS);

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        when(spyCheck.shouldReportThis(n, parent)).thenReturn(false);

        spyCheck.visit(t, n, parent);

        verify(compiler, never()).report(any());
    }

    @Test
    public void testVisit_NotThis() {
        // Setup: n is not THIS
        when(n.getType()).thenReturn(Token.NAME);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler, never()).report(any());
    }

    @Test
    public void testVisit_ClearsAssignLhsChild() {
        // Setup: n is the assignLhsChild
        setAssignLhsChild(checkGlobalThis, n);

        // Ensure n is not THIS to avoid side effects from the first IF
        when(n.getType()).thenReturn(Token.NAME);

        checkGlobalThis.visit(t, n, parent);

        assert(getAssignLhsChild(checkGlobalThis) == null);
    }

    @Test
    public void testVisit_DoesNotClearAssignLhsChildIfDifferentNode() {
        // Setup: n is NOT the assignLhsChild
        Node otherNode = mock(Node.class);
        setAssignLhsChild(checkGlobalThis, n);

        when(otherNode.getType()).thenReturn(Token.NAME);

        checkGlobalThis.visit(t, otherNode, parent);

        assert(getAssignLhsChild(checkGlobalThis) == n);
    }

    @Test
    public void testVisit_BothConditionsTrue() {
        // Setup: n is THIS, shouldReport is true, AND n is assignLhsChild
        when(n.getType()).thenReturn(Token.THIS);
        setAssignLhsChild(checkGlobalThis, n);

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        // Re-inject compiler to the spy
        setCompiler(spyCheck, compiler);
        when(spyCheck.shouldReportThis(n, parent)).thenReturn(true);
        when(t.makeError(any(), any(), any())).thenReturn(error);

        spyCheck.visit(t, n, parent);

        verify(compiler).report(error);
        assert(getAssignLhsChild(spyCheck) == null);
    }
}
